// ---------- BookingID (max-scan across ALL existing IDs) ----------
const bookingItems = $items("Find documents");
let maxBookingNumber = 1000;
for (const it of bookingItems) {
  const id = it.json && it.json.BookingID;
  if (typeof id === "string") {
    const m = id.match(/^B(\d+)$/);
    if (m) maxBookingNumber = Math.max(maxBookingNumber, parseInt(m[1], 10));
  }
}
const newBookingId = `B${maxBookingNumber + 1}`;

// ---------- GuestID (max-scan across ALL existing IDs) ----------
const guestItems = $items("Find documents1");
let maxGuestNumber = 99;
for (const it of guestItems) {
  const id = it.json && it.json.GuestID;
  if (typeof id === "string") {
    const m = id.match(/^G(\d+)$/);
    if (m) maxGuestNumber = Math.max(maxGuestNumber, parseInt(m[1], 10));
  }
}
const newGuestId = `G${maxGuestNumber + 1}`;

return [
  {
    json: {
      BookingID: newBookingId,
      GuestID: newGuestId
    }
  }
];

// 1️⃣ Webhook payload (REAL location)
// const body = $json.body ?? {};
const body = $('Webhook2').first().json.body ?? {};

// 2️⃣ Generated IDs
const ids = $items("Code in JavaScript2")[0].json;

// 3️⃣ Normalize ObjectId
const normalizeObjectId = (val) => {
  if (val?.$oid) return val.$oid;
  if (typeof val === "string") return val;
  return null;
};

// 4️⃣ Normalize Numbers (Supabase Extended JSON safe)
const normalizeNumber = (val) => {
  if (val?.$numberInt) return Number(val.$numberInt);
  if (val?.$numberLong) return Number(val.$numberLong);
  if (typeof val === "number") return val;
  if (typeof val === "string") return Number(val);
  return null;
};

// 5️⃣ Final clean payload
const finalPayload = {
  // IDs
  BookingID: ids.BookingID,
  GuestID: ids.GuestID,

  // Session
  sessionId: body.sessionId ?? null,

  // Booking info
  RoomID: body.RoomID ?? null,
  buildingID: String(body.RoomID ?? "").startsWith("2") ? "B2" : "B1",
  CheckInDate: body.CheckInDate ?? null,
  CheckOutDate: body.CheckOutDate ?? null,
  NumGuests: normalizeNumber(body.NumGuests),
  TotalRoomAmount: normalizeNumber(body.TotalRoomAmount),

  // Guest info
  FullName: body.FullName ?? null,
  Email: body.Email ?? null,
  Phone: body.Phone ?? null,
  CNIC: body.CNIC ?? null,
  Nationality: body.Nationality ?? null,
  Notes: body.Notes ?? null
};

return [
  {
    json: finalPayload
  }
];

const raw = $input.first().json.output;

// If already an object → pass through
if (typeof raw === 'object' && raw !== null) {
  return [{ json: raw }];
}

// If string → try to parse JSON
if (typeof raw === 'string') {
  const trimmed = raw.trim();

  try {
    const parsed = JSON.parse(trimmed);
    return [{ json: parsed }];
  } catch (e) {
    // Not JSON → send as text
    return [
      {
        json: {
          text: trimmed,
          isJson: false
        }
      }
    ];
  }
}

// Fallback
return [
  {
    json: {
      text: String(raw),
      isJson: false
    }
  }
];

const input = $input.first().json || {};
const b = (input.body && typeof input.body === 'object') ? input.body : {};

// Extract message text from any supported shape (never throws)
let rawMsg = "";
try {
  const m = b.message;
  if (typeof m === "string") rawMsg = m;
  else if (m && typeof m === "object" && typeof m.text === "string") rawMsg = m.text;
  else if (typeof b.chatInput === "string") rawMsg = b.chatInput;
  else if (typeof b.text === "string") rawMsg = b.text;
} catch (e) { rawMsg = ""; }
if (typeof rawMsg !== "string") rawMsg = String(rawMsg ?? "");

const msg = rawMsg.toLowerCase();

// Session ID with safe fallback instead of throwing (Fix 7: garbage input -> HTTP 500)
let sessionId = null;
try { sessionId = b.sessionId ?? input.sessionId ?? null; } catch (e) {}
if (!sessionId) {
  sessionId = `sess-unknown-${Date.now()}`;
}

// Workflow memory + intent routing (original behavior for well-formed payloads)
const store = $getWorkflowStaticData('global');
if (!store.sessions) {
  store.sessions = {};
}
let intent = store.sessions[sessionId];
if (!intent) {
  intent = "new_booking";
}
if (
  msg.includes("update") ||
  msg.includes("change") ||
  msg.includes("modify")
) {
  intent = "update_booking";
}
if (
  msg.includes("new booking") ||
  msg.includes("book room") ||
  msg.includes("make booking")
) {
  intent = "new_booking";
}
if (msg.includes("cancel")) {
  intent = "cancel_booking";
}
store.sessions[sessionId] = intent;

// Normalized body: guarantee the fields downstream expressions read
// ($json.body.message.text for the update/cancel agents,
//  $json.body.chatInput for the booking agent, body.sessionId for Respond nodes)
const agentText = rawMsg || "Hello";
const nb = { ...b, sessionId };
nb.message = (b.message && typeof b.message === "object") ? { ...b.message } : {};
if (typeof nb.message.text !== "string" || !nb.message.text) nb.message.text = agentText;
if (typeof nb.chatInput !== "string" || !nb.chatInput) nb.chatInput = agentText;

return [
  {
    json: {
      ...input,
      ...nb,
      body: nb,
      intent,
      _debug: {
        rawMsg,
        sessionId,
        intentLocked: true
      }
    }
  }
];

