const input = $input.first().json || {};
const b = (input.body && typeof input.body === 'object') ? input.body : input;
// Retell custom tools (args_at_root: true) spread args at the JSON root next to
// "name" and "call". Tolerate args nested under body.args as well.
const args = {};
if (b.args && typeof b.args === 'object' && !Array.isArray(b.args)) {
  for (const k of Object.keys(b.args)) args[k] = b.args[k];
}
for (const k of Object.keys(b)) {
  if (k === 'name' || k === 'call' || k === 'args') continue;
  if (args[k] === undefined) args[k] = b[k];
}
const tool = (typeof b.name === 'string' && b.name) ? b.name
  : (typeof args.name === 'string' ? args.name : '');
const callId = (b.call && b.call.call_id) || null;
const sessionId = 'retell-' + (callId || ('ts' + Date.now()));
return [{ json: { tool, args, sessionId, callId } }];

function extract(j) {
  if (j == null) return '';
  if (typeof j === 'string') return j;
  if (typeof j === 'object') {
    if (typeof j.data === 'string' && j.data) return j.data;
    if (typeof j.text === 'string' && j.text) return j.text;
    if (typeof j.output === 'string' && j.output) return j.output;
    if (typeof j.response === 'string' && j.response) return j.response;
    if (j.body != null) return extract(j.body);
    return '';
  }
  return String(j);
}
let text = '';
try { text = extract($input.first().json); } catch (e) { text = ''; }
text = (text || '').trim();
if (!text) text = 'Sorry, I could not complete that request.';
return [{ json: { response: text } }];

