// Room + amount derivation (the Retell tool carries room_type, not a RoomID,
// and no total): mirror the proven harness payload by resolving a concrete
// free room of the requested type and pricing it from the rooms table.
const p = $('Parse Retell Tool Call').first().json;
const a = p.args || {};
const bk = a.booking || {};
const gu = a.guest || {};
const ci = bk.check_in || null;
const co = bk.check_out || null;
const numGuests = Number(bk.adults || 1) + Number(bk.children || 0);
const rawType = String(bk.room_type || 'Standard').toLowerCase();
const typeName = rawType.includes('suite') ? 'Suite'
  : (rawType.includes('deluxe') ? 'Deluxe' : 'Standard');
const rooms = $('List Rooms For Create').all().map(i => i.json).filter(r => r && r.RoomID);
const bookings = $input.all().map(i => i.json).filter(x => x && x.BookingID);
const busy = new Set(bookings
  .filter(b => String(b.BookingStatus || '').toLowerCase() !== 'cancelled'
    && ci && co && b.CheckInDate < co && ci < b.CheckOutDate)
  .map(b => b.RoomID));
let cands = rooms.filter(r => r.TypeName === typeName && !busy.has(r.RoomID));
let fits = cands.filter(r => Number(r.Capacity || 0) >= numGuests);
if (!fits.length) fits = cands;
fits.sort((x, y) => String(x.RoomID).localeCompare(String(y.RoomID)));
const room = fits[0] || null;
const nights = (ci && co) ? Math.round((Date.parse(co) - Date.parse(ci)) / 86400000) : 0;
const marker = 'Retell tool booking ' + (p.callId || p.sessionId);
const out = { sessionId: p.sessionId, marker, noRoom: !room || !(nights > 0),
  roomType: typeName, nights, checkIn: ci, checkOut: co, guestEmail: gu.email || '' };
if (room && nights > 0) {
  const total = nights * Number(room.RatePerNight || 0);
  out.roomId = room.RoomID;
  out.total = total;
  out.payload = {
    sessionId: p.sessionId + '-create',
    RoomID: room.RoomID,
    CheckInDate: ci,
    CheckOutDate: co,
    NumGuests: numGuests,
    TotalRoomAmount: total,
    FullName: gu.full_name || '',
    Email: gu.email || '',
    Phone: gu.phone || '',
    CNIC: a.cnic || gu.cnic || null,
    Nationality: gu.country || null,
    Notes: marker
  };
}
return [{ json: out }];

